// Généré depuis src/data/upgradeTexts.ts (node scripts/generate-fiches-upgrades.mjs).
window.SWL_UPGRADE_TEXTS={"2 1b medical droid":{"text":"Soldat Rebelle ▲ uniquement. Ajoutez 1 figurine de Droïde Médical 2-1B. Non-combattant. Traiter 1 : Capacité 2 (action).","use":"passive"},"88i twin light blaster":{"text":"TR-TT uniquement. Arme : Blasters Légers Jumelés 88i (portée 1-3) — 1 dé rouge, 1 dé blanc, 1 dé noir ; Fixe : avant, Impact 1.","use":"passive"},"a280 cfe pistol sniper config":{"text":"Cassian Andor uniquement. Reconfiguration. Arme : Fusil A280 (portée 1 et au-delà) — 1 dé rouge, 1 dé noir ; Encombrant, Haute Vélocité, Perforant 1. (Carte à deux faces : l'autre face porte la configuration pistolet.)","use":"passive"},"academy trained":{"text":"{\"title\":\"•Formé à l'Académie\",\"body\":\"**Officier Impérial uniquement.**\\nAugmentez le {courage} de cette unité de 1.\\nCette unité gagne **Exemplaire**, **Inspiration 1** et {action}**Stratège 1**.\"}","use":"passive"},"additional supplies":{"text":"À la fin de l'activation de cette unité, vous pouvez supprimer cette carte de la partie (icône ✖). Dans ce cas, redressez 1 des améliorations non-Ordonnance de cette unité.","use":"discard"},"ag 2g quad laser":{"text":"Camion Speeder A-A5 uniquement. Arme : Quadrilaser AG-2G (portée 1-3) — 6 dés noirs ; Impact 2.","use":"passive"},"anger":{"text":"Côté Obscur uniquement. Quand cette unité subit au moins 1 blessure, après que l'effet a été résolu, elle gagne 1 pion Viser.","use":"passive"},"anti bunker shells":{"text":"Cycle. Arme : Obus « Antibunker » (portée 1-2) — 3 dés blancs, 1 dé noir ; Fixe : avant, Déflagration, Dispersion.","use":"passive"},"armor piercing shells":{"text":"Cycle. Arme : Obus Antiblindage (portée 2-3) — 1 dé rouge, 2 dés noirs ; Fixe : avant, Impact 3.","use":"passive"},"ascension cables":{"text":"Action de carte gratuite (↱») : cette unité gagne Ascension jusqu'à la fin de son activation.","use":"exhaust"},"at rt flamethrower":{"text":"TL-TT uniquement. Arme : Lance-flammes (corps-à-corps et portée 1) — 2 dés noirs ; Fixe : avant, Déflagration, Souffle.","use":"passive"},"at st mortar launcher":{"text":"TR-TT uniquement. Arme : Lance-mortier de TR-TT (portée 4 et au-delà) — 3 dés blancs ; Fixe : avant, Suppressif.","use":"passive"},"attack protocols":{"text":"Véhicule uniquement. Cette unité gagne IA : Viser et Précis 2.","use":"passive"},"ax 108 ground buzzer":{"text":"Airspeeder T-47 uniquement. Arme : Ax-108 « Ground Buzzer » (portée 1-2) — 4 dés noirs ; Fixe : arrière.","use":"passive"},"axe ewok":{"text":"{\"title\":\"Ewok avec Hache\",\"body\":\"**Frondeurs Ewoks ou Escarmoucheurs Ewoks uniquement.**\\nAjoutez 1 figurine d'Ewok avec Hache.\",\"weapons\":[{\"name\":\"Hache de Pierre\",\"keywords\":\"Impact 1, Perforant 1\"}]}","use":"passive"},"baron rudor":{"text":"Véhicule à répulseurs Empire uniquement. Cette unité gagne Tireur Embusqué. Après que cette unité a effectué une action Récupérer, elle gagne 1 pion Viser.","use":"passive"},"barrage generator":{"text":"Quand cette unité effectue une attaque avec une arme à distance qui a Fixe, pendant l'étape « Constituer la réserve d'attaque », vous pouvez incliner cette carte (↱). Dans ce cas, ajoutez 2 dés d'attaque blancs à la réserve d'attaque et elle gagne Suppressif.","use":"exhaust"},"battle shield wookiee":{"text":"Au début de l'activation de cette unité, vous pouvez retourner cette carte (bouton « Retourner la carte » de la fiche) : la vitesse maximale de cette unité est réduite de 1 et elle gagne Armure 1 (Armure 1 n'est active que carte retournée).","use":"passive"},"battlemaster":{"text":"Chef Mandalorien ou Chasseur Mandalorien uniquement. Cette unité gagne La Mort Venue du Ciel. La première fois de chaque partie que cette unité devrait ✖ une carte Amélioration (équipement, armement ou clan), cette carte Amélioration est ↱ à la place.","use":"passive"},"beskad duelist":{"text":"Résistance Mandalorienne uniquement. Ajoutez 1 figurine de Duelliste avec Beskad. Cette unité gagne Duelliste. Arme : Vibrolame (corps-à-corps) — 2 dés rouges.","use":"passive"},"black sun crew":{"text":"{\"title\":\"Équipage du Soleil Noir\",\"body\":\"**Tank Speeder WLO-5 uniquement.**\\nCette unité perd l'affiliation Pirates et gagne l'affiliation Soleil Noir.\\nAu début de la __Phase d'Activation__, cette unité gagne 1 pion Viser ou 1 pion Esquive s'il y a au moins 1 autre unité Soleil Noir alliée à portée 1 de cette unité.\"}","use":"passive"},"black sun enforcer concealment":{"text":"Cette unité conserve Cache : Esquive 1 même si la figurine ajoutée par cette carte est vaincue.","use":"passive"},"black sun enforcer magnetic detonator":{"text":"Hommes de Main du Soleil Noir uniquement. Ajoutez 1 figurine d'Homme de Main avec Détonateur Magnétique. Arme : Détonateur Magnétique (corps-à-corps et portée 1) — 3 dés noirs ; Déflagration, Impact 3.","use":"passive"},"black sun enforcer scatter gun":{"text":"Hommes de Main du Soleil Noir uniquement. Ajoutez 1 figurine d'Homme de Main avec Fusil à Dispersion. Arme : Fusil à Dispersion (corps-à-corps et portée 1-2) — 2 dés rouges ; Perforant 1.","use":"passive"},"boba fett flamethrower":{"text":"Boba Fett uniquement. Arme : Projecteur de Flammes (corps-à-corps et portée 1) — 1 dé rouge ; Déflagration, Souffle, Suppressif.","use":"passive"},"bowcaster wookiee":{"text":"Guerriers Wookies uniquement. Ajoutez 1 figurine de Wookie avec Arbalète. Arme : Arbalète (portée 1-3) — 1 dé rouge, 1 dé blanc ; Impact 1, Perforant 1.","use":"passive"},"burst of speed":{"text":"Au début de l'activation de cette unité, vous pouvez supprimer cette carte de la partie (icône ✖) pour considérer que la vitesse maximale de cette unité est 3 jusqu'à la fin du round. Dans ce cas, pendant la Phase Finale, cette unité gagne 1 pion Immobilisation.","use":"discard"},"c 3po golden god":{"text":"{\"name\":\"C-3PO\",\"subtitle\":\"Dieu Doré\",\"type\":\"Soldat Droïde\",\"keywords\":[\"{action}Maître Conteur\",\"Contrainte : soldat Ewok\",\"Influence Divine\",\"Infiltration\"]}","use":null},"cad bane electro gauntlets":{"text":"Cad Bane uniquement. Tant que cette unité est engagée, elle peut effectuer des déplacements normalement si une unité avec laquelle elle est engagée a 1 ou plusieurs pions Immobilisation.","use":"passive"},"call to arms":{"text":"{\"title\":\"Appel aux Armes\",\"body\":\"**Soldat Ewok uniquement.**\\n{incliner}{action-gratuite}Cette unité gagne **Charge** jusqu'à la fin du round. Cette unité gagne 1 pion Suppression.\"}","use":"exhaust"},"captain rex":{"text":"Unique, Soldat Clone uniquement. Ajoute 1 figurine du Capitaine Clone Rex (Chef). Cette unité augmente de 1 son courage et gagne 1 icône d'amélioration Personnel et 1 icône d'amélioration Ordonnance. Quand cette unité vainc une unité ennemie grâce à une attaque, après que l'action d'attaque a été résolue, elle peut effectuer 1 action gratuite.","use":"passive"},"cassian andor operative":{"text":"Carte à deux faces (face A au départ). Unité Rebelle ▲ uniquement. Ajoute 1 figurine de Cassian Andor. Chef. Cette unité augmente de 1 son courage et gagne 1 icône d'amélioration Personnel. FACE A : Profil Bas et Mission Secrète ; arme A280 Configuration Sniper. Quand au moins 1 figurine de cette unité est vaincue, vous pouvez retourner la carte (bouton « Retourner la carte » de la fiche). FACE B : le courage de cette unité devient « - » ; Coup de Chance 1 ; une fois par tour, quand cette unité constitue une réserve d'attaque, ajoutez 1 dé d'attaque blanc par figurine de cette unité précédemment vaincue ; arme Opérations Secrètes.","use":"passive"},"champion of the watch":{"text":"Soldat Mandalorien commandant ou Soldat Mandalorien agent uniquement. Cette unité change son Affiliation en Enfants de la Ronde. Cette unité gagne Telle est la Voie : Viser 1 ou Esquiver 1.","use":"passive"},"chewbacca upgrade":{"text":"Soldats Wookies uniquement. Ajoutez 1 figurine de Chewbacca (3 PV). Quand cette unité attaque, pendant l'étape Former la Réserve d'Attaque, choisissez 1 de ses réserves d'attaque : cette unité peut améliorer 1 dé d'attaque de cette réserve pour chaque figurine qui y ajoute une arme. Quand cette unité défend, pour chaque figurine de l'unité, vous pouvez améliorer 1 de ses dés de défense. Chef. Arme : Arbalète-laser de Chewbacca (portée 1-3) — 1 dé rouge, 2 dés blancs ; Impact 1.","use":"passive"},"clairvoyance":{"text":"Quand cette unité attaque, elle peut supprimer cette carte de la partie (icône ✖) pendant l'étape « Relancer les dés d'attaque » : elle relance tous ses dés d'attaque, puis convertit normalement tout résultat Adrénaline d'attaque ; ce jet ne peut plus être modifié ensuite. Quand cette unité défend, elle peut supprimer cette carte (✖) pendant l'étape « Relancer les dés » : elle relance tous ses dés de défense, puis convertit normalement tout résultat Adrénaline de défense ; ce jet ne peut plus être modifié.","use":"discard"},"climbing cables":{"text":"Action de carte gratuite (↱») : cette unité gagne Ascension jusqu'à la fin de son activation.","use":"exhaust"},"cm o 93 trooper":{"text":"Vétérans Rebelles uniquement. Ajoutez 1 figurine de Soldat avec CM-O/93. Arme : CM-O/93 (portée 1-4) — 4 dés blancs ; Critique 2.","use":"passive"},"combat armor rebel":{"text":"Agent Rebelle ou Officier Rebelle uniquement. La défense de cette unité devient rouge au lieu de blanche, et cette unité n'a plus son adrénaline de défense (Adrénaline : Bloc).","use":"passive"},"combat group leader":{"text":"Unité ▲ uniquement. Lors de la mise en place, cette unité peut choisir une unité de troupes alliée qui a la même affiliation ou faction qu'elle. Au début de chaque Phase d'Activation, l'unité choisie gagne 1 pion Viser ou 1 pion Esquive si elle est à ② de cette unité. De plus, l'unité choisie peut prêter main-forte à cette unité.","use":"passive"},"command and control uplink":{"text":"{\"title\":\"•Liaison de Commandement et de Contrôle\",\"body\":\"**Agent Impérial ou Officier Impérial uniquement.**\\nPendant la __Phase de Commandement__, après avoir révélé les cartes de Commandement mais avant de déterminer la priorité, vous pouvez défausser cette carte. Dans ce cas, votre carte de Commandement révélée compte comme ayant 1 pip de moins jusqu'à la fin du round.\"}","use":"discard"},"command system":{"text":"Véhicule uniquement. Quand cette unité utilise Coordination, elle peut donner un ordre à une unité à ② au lieu de ①.","use":"passive"},"comms hacking unit":{"text":"Pendant l'étape « Donner des ordres » de la Phase de Commandement, après qu'une unité ennemie à ① de cette unité a reçu un ordre, cette unité peut se donner un ordre à elle-même.","use":"passive"},"comms jammer":{"text":"Les unités ennemies à ① de cette unité ne peuvent pas recevoir d'ordres, sauf si elles se donnent un ordre à elles-mêmes.","use":"passive"},"concussion grenades":{"text":"Arme : Grenade à Concussion (portée 1) — 1 dé noir ; Déflagration.","use":"passive"},"cr 24 flame rifle":{"text":"Soldat Monté sur Dewback uniquement. Arme : Fusil Lance-flammes CR-24 (corps-à-corps et portée 1) — 1 dé blanc, 1 dé noir ; Déflagration, Souffle.","use":"passive"},"crosshair":{"text":"Ajoute 1 figurine de Crosshair. Cette unité gagne Précis 1. Tant qu'une réserve d'attaque ne contient que l'arme Fusil Firepuncher, la réserve d'attaque gagne Critique 1.","use":"passive"},"defend in depth":{"text":"{\"title\":\"•Défense en Profondeur\",\"body\":\"**Agent Impérial ou Officier Impérial uniquement.**\\nPendant la __Phase Finale__, choisissez 1 unité de soldats alliée à portée 1 de cette unité. L'unité choisie ne retire pas 1 pion Viser.\\nCette unité gagne **Aide : unité de soldats Emplacement**, **Position Préparée** et {action}**Observateur 1**.\"}","use":"passive"},"defense protocols":{"text":"Véhicule uniquement. Cette unité gagne Agile, Manœuvre Improbable et IA : Esquive.","use":"passive"},"defensive posture":{"text":"Seule une unité qui a au moins 1 icône d'amélioration Amélioration de Combat peut s'équiper de cette carte. Au début de l'activation de cette unité, vous pouvez retourner cette carte. Quand cette unité effectue une action Esquiver, elle gagne 2 pions Esquive au lieu de 1. Cette unité ne peut pas dépenser de pions Viser.","use":"passive"},"defensive stance":{"text":"Seule une unité qui a au moins 1 icône d'amélioration Amélioration de Combat peut s'équiper de cette carte. Au début de l'activation de cette unité, vous pouvez retourner cette carte. Quand cette unité effectue une action Esquiver, elle gagne 2 pions Esquive au lieu de 1. Cette unité ne peut pas dépenser de pions Viser.","use":"passive"},"del meeko":{"text":"Forces Spéciales Impériales ou Soldat Impérial ▲ uniquement. Ajoutez 1 figurine de Del Meeko. Réparation 2 : Capacité 1 (action). Arme : DLT-19x de Del (portée 1-5) — 2 dés noirs ; Haute Vélocité, Létal 1.","use":"passive"},"dh 447 sniper":{"text":"Groupe de Combat Commandos Rebelles uniquement. Ajoutez 1 figurine de Sniper avec DH-447. Arme : Fusil de Sniper DH-447 (portée 2-5) — 2 dés blancs, 1 dé noir ; Haute Vélocité, Débordement, Équipe Sniper.","use":"passive"},"din djarin amban rifle":{"text":"Din Djarin uniquement. Action de carte (→→, consomme 2 actions) : si cette unité n'est pas engagée, elle peut effectuer un déplacement à vitesse 1. Ensuite, choisissez une unité ennemie en LdV et lancez 1 dé d'attaque rouge : sur un résultat Touche ou Critique, l'unité choisie subit 1 blessure et gagne 1 pion Suppression.","use":"exhaust"},"din djarin beskar spear":{"text":"Din Djarin uniquement. Cette unité gagne Duelliste. Arme : Lance en Beskar (corps-à-corps) — 2 dés rouges, 1 dé noir.","use":"passive"},"din djarin flamethrower":{"text":"Din Djarin uniquement. Arme : Projecteur de Flammes (corps-à-corps et portée 1) — 1 dé rouge ; Déflagration, Souffle, Suppressif.","use":"passive"},"din djarin jetpack":{"text":"Din Djarin uniquement. Augmentez de 1 la vitesse de cette unité. Cette unité gagne Saut 2 (action).","use":"passive"},"dlt 19 pintle mount":{"text":"Tank « Occupier » TX-225 GAVw uniquement. Arme : Fusil Blaster DLT-19 (portée 1-4) — 2 dés rouges ; Impact 1.","use":"passive"},"dlt 19 stormtrooper":{"text":"Stormtroopers uniquement. Ajoutez 1 figurine de Stormtrooper avec DLT-19. Arme : Fusil Blaster DLT-19 (portée 1-4) — 2 dés rouges ; Impact 1.","use":"passive"},"dlt 19d trooper":{"text":"Death Troopers Impériaux uniquement. Ajoutez 1 figurine de Soldat avec DLT-19D. Arme : Fusil Blaster DLT-19D (portée 1-4) — 2 dés rouges, 1 dé blanc ; Impact 1.","use":"passive"},"dlt 19x sniper":{"text":"Groupe de Combat Scout Troopers uniquement. Ajoutez 1 figurine de Sniper avec DLT-19x. Arme : Fusil de Sniper DLT-19x (portée 2-5) — 2 dés blancs, 1 dé noir ; Haute Vélocité, Débordement, Équipe Sniper.","use":"passive"},"dlt 20a range trooper":{"text":"Range Troopers uniquement. Ajoutez 1 figurine de Range Trooper avec DLT-20A. Arme : Fusil Blaster DLT-20A (portée 1-5) — 2 dés rouges ; Impact 2.","use":"passive"},"dlt 20a trooper":{"text":"Soldats Rebelles uniquement. Ajoutez 1 figurine de Soldat avec DLT-20A. Arme : Fusil Blaster DLT-20A (portée 1-4) — 1 dé blanc, 2 dés noirs ; Critique 1.","use":"passive"},"dread":{"text":"Côté Obscur uniquement. Tant que cette unité n'est pas engagée, lorsqu'une unité ennemie à ② et en LdV de cette unité effectue une attaque à distance ciblant une autre unité alliée, l'unité attaquante gagne 1 pion Suppression après avoir résolu l'attaque.","use":"passive"},"dt f16":{"text":"Death Troopers Impériaux uniquement. Ajoutez 1 figurine de DT-F16. Cette unité gagne Contrainte. Chef. Arme : Fusil Blaster E-11D (portée 1-3) — 1 dé blanc, 1 dé noir.","use":"passive"},"duck and cover":{"text":"Quand cette unité défend contre une attaque à distance, au début de l'étape « Appliquer les esquives et couverts », elle peut gagner 1 pion Suppression.","use":"passive"},"dw 3 concussion grenade launcher":{"text":"TR-TT uniquement. Arme : Lance-grenades DW-3 (portée 1-2) — 2 dés noirs ; Fixe : avant, Déflagration.","use":"passive"},"e 11d focused strike config":{"text":"Death Troopers Impériaux uniquement. Reconfiguration. Arme : E-11D Frappe Concentrée (portée 1-4) — 1 dé noir ; Suppressif. (Carte à deux faces : l'autre face porte l'autre configuration.)","use":"passive"},"echo clone force 99":{"text":"Le Bad Batch uniquement. Ajoutez 1 figurine d'Echo. Cette unité gagne Fiable 3.","use":"passive"},"electrobinoculars":{"text":"Cette unité gagne Observateur 1 (action de carte). Les unités de Droïdes de Combat B1 peuvent s'équiper de cette carte même si elles n'ont pas d'icône d'amélioration Équipement.","use":"passive"},"electrostaff pirate":{"text":"{\"title\":\"Pirate avec Électrobâton\",\"body\":\"**Pirates Weequays uniquement.**\\nAjoutez 1 figurine de Pirate avec Électrobâton.\\nCette unité gagne **Immunité : Perforant au Corps-à-Corps**.\",\"weapons\":[{\"name\":\"Électrobâton\",\"keywords\":\"Arme de Poing : Corps-à-Corps\"}]}","use":"passive"},"emergency stims":{"text":"Quand cette unité devrait subir 1 ou plusieurs blessures d'une attaque ennemie, vous pouvez incliner cette carte pour prévenir jusqu'à 2 de ces blessures et placer autant de pions Blessure sur cette carte à la place. Dans ce cas, à la fin de sa prochaine activation, cette unité retire chaque pion Blessure de cette carte et subit un nombre de blessures égal au nombre de pions Blessure ainsi retirés.","use":"exhaust"},"emergency transponder":{"text":"Au début de l'activation de cette unité, si elle a été activée grâce à un pion Ordre de la réserve d'ordres, vous pouvez supprimer cette carte de la partie (icône ✖). Dans ce cas, cette unité gagne 1 pion Viser ou 1 pion Esquive ou retire 1 pion Suppression.","use":"discard"},"emp grenades":{"text":"Arme : Grenades « Anti-droïdes » EMP (portée 1) — 1 dé noir ; Ion 1.","use":"passive"},"endurance":{"text":"À la fin de la Phase d'Activation, cette unité peut retirer 1 pion Suppression.","use":"passive"},"engagement protocols":{"text":"Véhicule uniquement. Cette unité gagne IA : Attaque, Déplacement.","use":"passive"},"entrenched":{"text":"Soldat en Position ou unité de soldats ayant Position Préparée uniquement (peut s'équiper même sans icône d'amélioration). Tant que cette unité est intégralement en territoire allié et qu'elle n'a pas de pion Ordre face cachée, elle lance des dés de défense rouges à la place des dés blancs quand elle lance sa réserve de couvert.","use":"passive"},"environmental gear":{"text":"Cette unité gagne Sans Entrave.","use":"passive"},"ewok skirmisher squad":{"text":"{\"title\":\"Escouade d'Escarmoucheurs Ewoks\",\"body\":\"**Escarmoucheurs Ewoks uniquement.**\\nAjoutez 4 figurines d'Escarmoucheur Ewok.\\nCette unité gagne **Indomptable**. Elle conserve ce mot-clé même si ces figurines sont vaincues.\\nCette unité est en cohésion si toutes ses figurines sont à portée 1 du chef d'unité, au lieu de portée ½. Elle conserve cette règle même si ces figurines sont vaincues.\\nCette unité ne peut pas être déployée ni recevoir d'ordre grâce au mot-clé **Transport**.\"}","use":"passive"},"ewok skirmishers":{"text":"{\"name\":\"Escarmoucheurs Ewoks\",\"type\":\"Soldat\",\"keywords\":[\"Mercenaire : {faction-rebelles}\",\"Profil Bas\",\"Sans Entrave\"],\"weapons\":[{\"name\":\"Lances\",\"keywords\":\"\"}]}","use":null},"ewok slinger squad":{"text":"{\"title\":\"Escouade de Frondeurs Ewoks\",\"body\":\"**Frondeurs Ewoks uniquement.**\\nAjoutez 4 figurines de Frondeur Ewok.\\nCette unité gagne **Indomptable**. Elle conserve ce mot-clé même si ces figurines sont vaincues.\\nCette unité est en cohésion si toutes ses figurines sont à portée 1 du chef d'unité, au lieu de portée ½. Elle conserve cette règle même si ces figurines sont vaincues.\\nCette unité ne peut pas être déployée ni recevoir d'ordre grâce au mot-clé **Transport**.\"}","use":"passive"},"ewok slingers":{"text":"{\"name\":\"Frondeurs Ewoks\",\"type\":\"Soldat\",\"keywords\":[\"Mercenaire : {faction-rebelles}\",\"Autonome : Adrénaline 1\",\"Profil Bas\",\"Cible 1\",\"Sans Entrave\"],\"weapons\":[{\"name\":\"Pierres\",\"keywords\":\"\"},{\"name\":\"Frondes\",\"keywords\":\"Primitif\"}]}","use":null},"ewok trapper":{"text":"{\"title\":\"Ewok Trappeur\",\"body\":\"**Frondeurs Ewoks ou Escarmoucheurs Ewoks uniquement.**\\nAjoutez 1 figurine d'Ewok Trappeur.\\nCette unité gagne 1 emplacement d'amélioration Entraînement.\"}","use":"passive"},"fear":{"text":"Côté Obscur uniquement. Cette unité gagne Démoraliser 1.","use":"passive"},"fire control":{"text":"Quand une autre unité alliée à ① effectue une attaque à distance contre une unité ennemie en LdV de cette unité, améliorez 2 des dés d'attaque de l'unité attaquante.","use":"passive"},"first sergeant arbmab":{"text":"Véhicule terrestre Impérial uniquement. Cette unité gagne Tacticien 1.","use":"passive"},"flametrooper":{"text":"Snowtroopers uniquement. Ajoutez 1 figurine de Flametrooper. Arme : Lance-flammes (corps-à-corps et portée 1) — 1 dé noir ; Déflagration, Souffle.","use":"passive"},"fleet trooper":{"text":"Soldats de la Flotte uniquement. Ajoutez 1 figurine de Soldat de la Flotte.","use":"passive"},"fleet trooper squad":{"text":"Soldats de la Flotte uniquement. Ajoutez 5 figurines de Soldat de la Flotte. Cette unité gagne Indomptable ; elle conserve ce mot-clé même si ces figurines ajoutées sont vaincues. Cette unité est en cohésion si toutes ses figurines sont à ① du Chef d'unité au lieu de ½ ; elle conserve cette règle même si ces figurines ajoutées sont vaincues. Cette unité ne peut pas être déployée ou recevoir des ordres via le mot-clé Transport.","use":"passive"},"force barrier":{"text":"Quand une autre unité de soldats alliée à ① de cette unité défend contre une attaque à distance, pendant l'étape « Modifier les dés d'attaque », vous pouvez incliner cette carte pour annuler soit 1 résultat Critique soit jusqu'à 2 résultats Touche.","use":"exhaust"},"force choke":{"text":"Côté Obscur uniquement. Choisissez une unité de soldats ennemie non-Massive, non-Énorme à ① de cette unité. L'unité choisie subit 1 blessure.","use":"exhaust"},"force guidance":{"text":"Action de carte gratuite (↱») : choisissez jusqu'à 2 unités alliées à ② de cette unité. Chaque unité choisie gagne 1 pion Adrénaline.","use":"exhaust"},"force push":{"text":"Action de carte gratuite (↱») : choisissez une unité de soldats ennemie à ① de cette unité. L'unité choisie effectue un déplacement à vitesse 1, même si elle est engagée. Vous résolvez ce déplacement.","use":"exhaust"},"force reflexes":{"text":"Action de carte gratuite (↱») : cette unité gagne 1 pion Esquive.","use":"exhaust"},"forest dwellers":{"text":"{\"title\":\"Habitants de la Forêt\",\"body\":\"**Soldats Ewoks uniquement.**\\nCette unité gagne **Éclaireur 1**.\\nAu début de la première __Phase d'Activation__, cette unité gagne 1 pion Esquive.\"}","use":"passive"},"fragmentation grenades":{"text":"Tant que cette arme est dans la réserve d'attaque, cette unité convertit ses adrénalines d'attaque en résultats Critique.","use":"passive"},"fx 9 medical droid":{"text":"Soldat Impérial ▲ uniquement. Ajoutez 1 figurine de Droïde Médical FX-9. Non-combattant. Traiter 1 : Capacité 2 (action).","use":"passive"},"galaar 90 sniper rifle armament":{"text":"Chef Mandalorien ou Chasseur Mandalorien uniquement. Cette unité gagne Tireur d'Élite 1. Fusil Sniper GALAAR-90 (1 rouge, 1 blanc, 1 noir, 1-5) : Haute Vélocité, Perforant 1.","use":"passive"},"gang boss":{"text":"{\"title\":\"•Chef de Gang\",\"body\":\"**Véhicule lourd Pirates uniquement.**\\nCette unité gagne **Pilotage de Véhicule 2**.\\nSeules les unités Pirates peuvent bénéficier du mot-clé **Pilotage de Véhicule X** de cette unité.\"}","use":"passive"},"gar saxon galar90 rifle":{"text":"Gar Saxon uniquement. Arme : Fusil Sniper Galar-90 (portée 1-4) — 1 dé rouge, 1 dé blanc, 1 dé noir ; Haute Vélocité, Létal 1, Longue Distance.","use":"passive"},"gas grenades":{"text":"{\"title\":\"Grenades à Gaz\",\"body\":\"**Trench Busters et Stormtroopers en Équipement Pluie uniquement.**\",\"weapons\":[{\"name\":\"Grenade à Gaz\",\"keywords\":\"Poison 1\"}]}","use":"passive"},"general tagge imperial high command":{"text":"{\"name\":\"Général Tagge\",\"subtitle\":\"Haut Commandement Impérial\",\"type\":\"Soldat\",\"keywords\":[\"{action}Calcul de Probabilités\",\"Équipe : Prouesse Logistique\",\"Exemplaire\",\"Inspiration 1\"],\"weapons\":[{\"name\":\"Non armé\",\"keywords\":\"\"},{\"name\":\"Blaster de Tagge\",\"keywords\":\"\"}]}","use":null},"general weiss":{"text":"Véhicule terrestre Impérial uniquement. Cette unité gagne Arsenal 2 et Commandant des Opérations.","use":"passive"},"generator overcharge":{"text":"Quand cette unité effectue une attaque avec une arme à distance qui a Fixe, pendant l'étape « Constituer la réserve d'attaque », vous pouvez incliner cette carte (↱). Dans ce cas, ajoutez 1 dé d'attaque noir à la réserve d'attaque et elle gagne Impact 1.","use":"exhaust"},"gideon hask":{"text":"Chef. Cette unité augmente de 1 son courage et gagne Coordination : Soldat ▲.","use":"passive"},"governor pryce":{"text":"Cette unité gagne Commandant des Opérations. Action de carte gratuite (») : choisissez une unité de soldats alliée à ② de cette unité ; elle gagne 1 pion Viser et 1 pion Suppression.","use":"passive"},"grand moff tarkin imperial high command":{"text":"{\"name\":\"Grand Moff Tarkin\",\"subtitle\":\"Haut Commandement Impérial\",\"type\":\"Soldat\",\"keywords\":[\"{action}Tirer les Ficelles : soldat {faction-empire}\",\"Entourage : Dark Vador\"],\"weapons\":[{\"name\":\"Mépris\",\"keywords\":\"\"}]}","use":null},"grapnel hooks":{"text":"Cette unité gagne Grimpeur Expérimenté.","use":"passive"},"handheld scanner":{"text":"Cette unité gagne Mettre à Couvert 1 (action de carte). Les unités de Droïdes de Combat B1 peuvent s'équiper de cette carte même si elles n'ont pas d'icône d'amélioration Équipement.","use":"passive"},"heavy blaster pistol":{"text":"{\"title\":\"Pistolet Blaster Lourd\",\"body\":\"**Agent Impérial ou Officier Impérial uniquement.**\\nCette unité gagne **Tireur d'Élite 1** et **Cible 1**.\",\"weapons\":[{\"name\":\"Pistolet Blaster Lourd\",\"keywords\":\"Létal 1, Longue Distance\"}]}","use":"passive"},"heavy laser retrofit":{"text":"Camion Speeder A-A5 uniquement. Arme : Canon Laser Lourd (portée 1-4) — 1 dé rouge, 1 dé blanc, 1 dé noir ; Critique 1.","use":"passive"},"herbal medicine":{"text":"{\"title\":\"•Médecine par les Plantes\",\"body\":\"**Logray uniquement.**\\n{incliner}{action-gratuite}Choisissez une unité de soldats Ewok alliée à portée 1 et en LdV. Retirez 1 blessure de l'unité choisie ou restaurez-lui 1 figurine vaincue.\"}","use":"exhaust"},"hh 12 stormtrooper":{"text":"Stormtroopers uniquement. Ajoutez 1 figurine de Stormtrooper avec HH-12. Arme : Lance-roquettes HH-12 (portée 2-4) — 3 dés noirs ; Encombrant, Impact 3.","use":"passive"},"high energy shells":{"text":"Cycle. Arme : Obus à Haute Énergie (portée 2-4) — 2 dés rouges, 1 dé blanc ; Fixe : avant, Critique 1, Haute Vélocité.","use":"passive"},"hit and run":{"text":"Unité ayant Speeder X uniquement (peut s'équiper même sans icône d'amélioration). Après que cette unité a effectué une action Attaquer, vous pouvez incliner cette carte pour effectuer une action Se déplacer.","use":"exhaust"},"hondo ohnaka trustworthy compatriot":{"text":"{\"name\":\"Hondo Ohnaka\",\"subtitle\":\"Compagnon Digne de Confiance\",\"type\":\"Soldat\",\"keywords\":[\"Mercenaire : {faction-empire}{faction-rebelles}{faction-republique}{faction-separatistes}\",\"Arsenal X. Retrait.\",\"Autonome : Esquive X\",\"Je Sens le Profit\",\"Agile. Fiable X\",\"Coup de Chance X\"],\"weapons\":[{\"name\":\"Ruse Weequay\",\"keywords\":\"\"},{\"name\":\"Blaster de Hondo\",\"keywords\":\"Polyvalent\"}]}","use":null},"hope":{"text":"Côté Lumineux uniquement. Cette unité gagne Inspiration 1.","use":"passive"},"hotshot pilot":{"text":"Véhicule à Répulseurs Rebelle uniquement. Cette unité gagne Tireur d'Élite 1.","use":"passive"},"hq uplink":{"text":"Pendant l'étape « Donner des ordres » de la Phase de Commandement, vous pouvez incliner cette carte. Dans ce cas, cette unité peut se donner un ordre à elle-même.","use":"exhaust"},"hunter":{"text":"Le Bad Batch uniquement. Ajoute 1 figurine de Hunter. Chef. Action de carte gratuite (») : choisissez une unité de soldats ennemie non-Massive, non-Énorme à ① et en LdV. Lancez 1 dé d'attaque noir : sur un résultat Touche ou Critique, l'unité choisie subit 1 blessure.","use":"exhaust"},"iden s id10 seeker droid":{"text":"Carte de compagnon d'Iden Versio : Soldat droïde « Droïde », 1 PV. Surveillance 1 (action), Alter Ego : Iden Versio, Recharger 1, Bouclier 1, Petit. Arme : Électrochoc (corps-à-corps et portée 1) — 3 dés blancs ; Suppressif.","use":"passive"},"ig11 nanny programming":{"text":"IG-11 uniquement. Lorsque vous créez votre armée, un Grogu allié gagne Alter Ego : IG-11. Cette unité gagne IA : Esquive, Déplacement.","use":"passive"},"ig11 prime programming":{"text":"IG-11 uniquement. Cette unité gagne Prime et IA : Viser, Attaque. Si elle choisit comme cible de Prime une unité d'un certain rang, ses armes gagnent Perforant 1 ; pour un autre rang, Suppressif (rangs exacts : voir la carte).","use":"passive"},"impact grenades":{"text":"Arme : Grenade à Impact (corps-à-corps et portée 1) — 1 dé noir ; Impact 4.","use":"passive"},"imperial agent bringing order to the galaxy":{"text":"{\"name\":\"Agent Impérial\",\"subtitle\":\"Faire Régner l'Ordre dans la Galaxie\",\"type\":\"Soldat\",\"keywords\":[\"Équipe : {emplacement-doctrine}\",\"Implacable\"],\"weapons\":[{\"name\":\"Entraînement au Combat\",\"keywords\":\"\"},{\"name\":\"Pistolet Blaster\",\"keywords\":\"\"}]}","use":null},"imperial comms technician":{"text":"Soldat Empire ▲ uniquement. Ajoute 1 figurine de Technicien Comms Impérial. Cette unité gagne 1 icône d'amélioration Comms et doit s'équiper d'au moins 1 amélioration Comms (contrainte de construction de liste).","use":"passive"},"imperial hammers elite armor pilot":{"text":"Véhicule terrestre Empire uniquement. Cette unité gagne l’adrénaline d’attaque « Adrénaline : Touche ».","use":"passive"},"imperial march":{"text":"Quand cette unité effectue une deuxième action Se déplacer au cours de son activation, augmentez sa vitesse de 1 pendant cette action. De plus, quand cette unité effectue une action Se déplacer au cours de son activation, vous pouvez supprimer cette carte de la partie (icône ✖) : cette unité gagne Charge jusqu'à la fin de son activation.","use":"discard"},"imperial mudtroopers":{"text":"{\"name\":\"Mudtroopers Impériaux\",\"type\":\"Soldat\",\"keywords\":[\"Sans Entrave\"],\"weapons\":[{\"name\":\"Matraque\",\"keywords\":\"\"},{\"name\":\"Fusil Blaster E-10\",\"keywords\":\"\"}]}","use":null},"imperial officer":{"text":"Soldat ▲ uniquement. Ajoute 1 figurine d'Officier Impérial. Chef. Cette unité augmente de 1 son courage et gagne Inspiration 1.","use":"passive"},"imperial officer ruthless efficiency":{"text":"{\"name\":\"Officier Impérial\",\"subtitle\":\"Efficacité Impitoyable\",\"type\":\"Soldat\",\"keywords\":[\"Équipe : {emplacement-doctrine}\",\"Inspiration 1\"],\"weapons\":[{\"name\":\"Entraînement au Combat\",\"keywords\":\"\"},{\"name\":\"Pistolet Blaster\",\"keywords\":\"\"}]}","use":null},"imperial probe droid":{"text":"{\"name\":\"Droïde Sonde Impérial\",\"type\":\"Soldat Droïde\",\"keywords\":[\"{action-gratuite}Surveillance 3\",\"{action-gratuite}Autodestruction 3\",\"Détachement : Forces Spéciales\",\"Retrait\",\"Infiltration\",\"Sustentation : Aérienne 1\"],\"weapons\":[{\"name\":\"Blaster Léger\",\"keywords\":\"\"}]}","use":null},"imperial probe droid upgrade":{"text":"{\"title\":\"Droïde Sonde Impérial\",\"body\":\"{faction-empire} **uniquement. Corps, Forces Spéciales ou Lourd uniquement.**\\nAjoutez 1 figurine de Droïde Sonde Impérial. Une unité de Corps gagne 1 emplacement d'amélioration Personnel.\\nQuand cette unité déclare une attaque contre une unité ennemie ayant au moins 1 pion Surveillance, pendant l'étape __Déclarer les Défenseurs__, vous pouvez dépenser 1 de ces pions et incliner cette carte : cette unité gagne 1 pion Viser.\\n{incliner}{action-gratuite}**Surveillance 1.**\\nAu début de chaque __Phase Finale__, redressez cette carte. **Non-combattant.**\"}","use":"exhaust"},"imperial tie pilot":{"text":"Véhicule à répulseurs uniquement. Augmentez de 1 la vitesse maximale de cette unité.","use":"passive"},"improvised orders":{"text":"Pendant la Phase d'Activation, après avoir pioché un pion Ordre dans votre réserve d'ordres, vous pouvez incliner cette carte (↱). Dans ce cas, piochez un second pion de cette réserve d'ordres et choisissez 1 des pions Ordre piochés à utiliser. Ensuite, remélangez l'autre pion Ordre dans votre réserve d'ordres. (Carte mise à jour : unique, elle ne se redresse plus automatiquement.)","use":"exhaust"},"in the fray":{"text":"Pendant la Phase d'Activation, quand une unité ennemie commence son activation à ① de cette unité, cette unité peut gagner 1 pion Adrénaline.","use":"passive"},"inquisitorius training":{"text":"La Septième Sœur uniquement. Cette unité gagne Démoraliser 1. Quand une unité ennemie à ① incline une amélioration (icône indiquée sur la carte), vous pouvez lancer un dé de défense rouge : sur un résultat Bloc ou Adrénaline, annulez l'effet de cette amélioration ; elle reste inclinée.","use":"passive"},"insatiable curiosity":{"text":"{\"title\":\"Curiosité Insatiable\",\"body\":\"**Frondeurs Ewoks ou Escarmoucheurs Ewoks uniquement.**\\n{action-gratuite}Cette unité peut défausser cette carte pour choisir une unité de soldats ennemie au contact du socle de son chef d'unité. Si l'unité choisie est équipée d'au moins 1 amélioration Personnel ou Équipement, défaussez l'une de ces améliorations non unique ou limitée. Cette unité subit ensuite 1 blessure.\"}","use":"discard"},"inspiring presence":{"text":"Les unités alliées à ④ de cette unité peuvent utiliser son courage lorsqu'elles vérifient si elles sont paniquées. Cette portée peut être réduite par d'autres effets.","use":"passive"},"jetpack rockets":{"text":"Résistance Mandalorienne uniquement. Arme : Roquettes Dorsales (portée 3-4) — 1 dé rouge ; Déflagration, Impact 1.","use":"passive"},"jyn s se 14 blaster":{"text":"K-2SO uniquement. Si votre armée contient Jyn Erso, réduisez de 5 les points de cette carte. Arme : Blaster SE-14 (portée 1-2) — 5 dés blancs ; Perforant 1, Suppressif.","use":"passive"},"kallus the operative":{"text":"Unité Empire ▲ ou ▼▲ uniquement. Ajoute 1 figurine de l'Agent Kallus. Chef. Cette unité augmente de 1 son courage, gagne Démoraliser 1 et 1 icône d'amélioration Personnel. Action de carte gratuite (↱») : choisissez une unité ennemie engagée avec cette unité ; elle gagne 2 pions Immobilisation. Arme de Poing : à distance.","use":"exhaust"},"kraken":{"text":"Unique, Soldat Droïde uniquement. Ajoute 1 figurine de Kraken (Chef). Cette unité gagne 1 icône d'amélioration Ordonnance et perd IA. Quand cette unité attaque, elle peut améliorer 1 dé d'attaque pour chaque figurine de cette unité qui a été précédemment vaincue.","use":"passive"},"kx series security droids":{"text":"Escouade Stormtrooper Antiémeute uniquement. Ajoutez 2 figurines de Droïde de Sécurité de Série KX. Arme : Oppression (corps-à-corps) — 1 dé rouge ; Impact 1.","use":"passive"},"lead by example":{"text":"Cette unité gagne Inspiration 2.","use":"passive"},"linked targeting array":{"text":"Soldat en Position ou Véhicule uniquement. Cette unité gagne Cible 1.","use":"passive"},"logistical prowess":{"text":"{\"title\":\"Prouesse Logistique\",\"body\":\"**Général Tagge uniquement.**\\nAu début de l'activation de cette unité, elle peut retirer autant de pions de cette carte qu'elle le souhaite pour gagner les pions correspondants.\\nQuand cette unité se choisit elle-même lors d'une action {action}**Calcul de Probabilités**, au lieu de gagner 1 pion Viser et 1 pion Esquive, cette carte peut gagner 1 pion Adrénaline, et 1 pion Viser ou 1 pion Esquive.\\n**Cache : Viser 1, Esquive 1.**\"}","use":"passive"},"logray superstitious shaman":{"text":"{\"name\":\"Logray\",\"subtitle\":\"Chaman Superstitieux\",\"type\":\"Soldat\",\"keywords\":[\"Aide : soldat Ewok\",\"Autonome : Viser 1 ou Esquive 1\",\"Inspiration 2\",\"Profil Bas\",\"Agile\"],\"weapons\":[{\"name\":\"Bâton\",\"keywords\":\"Suppressif\"}]}","use":null},"long gun wookiee":{"text":"Guerriers Wookies uniquement. Ajoutez 1 figurine de Wookie avec Arme d'Épaule. Arme : Arme d'Épaule (portée 1-4) — 2 dés noirs ; Suppressif.","use":"passive"},"long rifle pirate":{"text":"{\"title\":\"Pirate avec Fusil Long\",\"body\":\"**Pirates Weequays uniquement.**\\nAjoutez 1 figurine de Pirate avec Fusil Long.\",\"weapons\":[{\"name\":\"Fusil Long\",\"keywords\":\"Létal 1\"}]}","use":"passive"},"m 45 ion blaster":{"text":"Landspeeder X-34 uniquement. Arme : Blaster Ionique M-45 (portée 1-4) — 2 dés blancs, 2 dés noirs ; Fixe : avant, Critique 1, Impact 1, Ion 1.","use":"passive"},"mandalorian combat shields":{"text":"Résistance Mandalorienne uniquement. Cette unité gagne Bouclier 2.","use":"passive"},"mertalizer":{"text":"{\"title\":\"Dark Trooper avec Mertaliseur\",\"body\":\"**Dark Troopers Impériaux uniquement.**\\nAjoutez 1 figurine de Dark Trooper avec Mertaliseur.\",\"weapons\":[{\"name\":\"Mertaliseur\",\"keywords\":\"Suppressif\"}]}","use":"passive"},"mission objective":{"text":"Soldat uniquement. Quand cette unité attaque une unité ennemie qui détient ou conteste au moins 1 pion Objectif, pendant l'étape « Relancer les dés d'attaque », vous pouvez incliner cette carte (↱) : cette unité relance 1 dé d'attaque. Au début de l'activation de cette unité, redressez cette carte.","use":"exhaust"},"mo dk power harpoon":{"text":"Airspeeder T-47 uniquement. Arme : Harpon Magnétique Mo/Dk (portée 1-2) — 1 dé rouge ; Fixe : arrière, Impact 1, Câble de Remorquage.","use":"passive"},"mounted gunners":{"text":"Véhicule ayant Transport uniquement (peut s'équiper même sans icône d'amélioration). Après que cette unité a effectué une action Attaquer pendant son activation, si elle n'a pas ajouté cette arme à une réserve d'attaque lors de cette action, elle peut effectuer une action Attaquer gratuite en n'utilisant que cette arme, même si elle a déjà attaqué ce tour.","use":"passive"},"mpl 57 barrage trooper":{"text":"Soldats de la Flotte uniquement. Ajoutez 1 figurine de Soldat avec MPL-57 de Barrage. Cycle. Arme : MPL-57 de Barrage (portée 1-3) — 2 dés blancs, 1 dé noir ; Déflagration, Impact 2.","use":"passive"},"mpl 57 ion trooper":{"text":"Soldats Rebelles uniquement. Ajoutez 1 figurine de Soldat avec MPL-57 à Ions. Arme : MPL-57 à Ions (portée 1-3) — 1 dé blanc, 2 dés noirs ; Critique 1, Impact 1, Ion 1.","use":"passive"},"mudtrooper squad":{"text":"{\"title\":\"Escouade Mudtrooper\",\"body\":\"**Mudtroopers Impériaux uniquement.**\\nAjoutez 4 figurines de Mudtrooper.\\nCette unité gagne **Indomptable**. Elle conserve ce mot-clé même si ces figurines sont vaincues.\\nCette unité est en cohésion si toutes ses figurines sont à portée 1 du chef d'unité, au lieu de portée ½. Elle conserve cette règle même si ces figurines sont vaincues.\\nCette unité ne peut pas être déployée ni recevoir d'ordre grâce au mot-clé **Transport**.\"}","use":"passive"},"offensive posture":{"text":"Seule une unité qui a au moins 1 icône d'amélioration Amélioration de Combat peut s'équiper de cette carte. Au début de l'activation de cette unité, vous pouvez retourner cette carte. Quand cette unité effectue une action Viser, elle gagne 2 pions Viser au lieu de 1. Cette unité ne peut pas dépenser de pions Esquive.","use":"passive"},"offensive push":{"text":"Action (carte à incliner ↱) : pendant sa prochaine action Se déplacer de cette activation, cette unité gagne Tacticien 1.","use":"exhaust"},"offensive stance":{"text":"Seule une unité qui a au moins 1 icône d'amélioration Amélioration de Combat peut s'équiper de cette carte. Au début de l'activation de cette unité, vous pouvez retourner cette carte. Quand cette unité effectue une action Viser, elle gagne 2 pions Viser au lieu de 1. Cette unité ne peut pas dépenser de pions Esquive.","use":"passive"},"old jedi trick":{"text":"Côté Lumineux uniquement. Action de carte gratuite (↱») : choisissez une unité de soldats ennemie non-Massive, non-Énorme à ② de cette unité. L'unité choisie gagne 2 pions Suppression.","use":"exhaust"},"on the hunt":{"text":"Quand cette unité attaque une unité de soldats qui a au moins 1 pion Blessure, elle peut gagner 1 pion Viser pendant l'étape « Lancer les dés d'attaque ».","use":"passive"},"onboard comms channel":{"text":"Véhicule uniquement. Cette unité gagne Coordination : Soldat.","use":"passive"},"onward to victory":{"text":"{\"title\":\"•En Avant vers la Victoire\",\"body\":\"**Logray uniquement.**\\nAu début de la __Phase d'Activation__, vous pouvez incliner cette carte. Dans ce cas, au début de la __Phase Finale__ suivante, défaussez cette carte. Tant que cette carte est inclinée, chaque fois qu'une unité ennemie est vaincue, après la résolution de l'effet, 1 unité de soldats Ewok alliée peut effectuer un déplacement à vitesse 1.\"}","use":"discard"},"outer rim speeder jockey":{"text":"Véhicule à Répulseurs Rebelle uniquement. Cette unité gagne Couvert 1.","use":"passive"},"pirate captain":{"text":"{\"title\":\"Capitaine Pirate\",\"body\":\"**Tank Speeder WLO-5 uniquement.**\\n{action-gratuite}Choisissez 1 unité Pirates à portée 1 de cette unité. L'unité choisie retire 1 pion Suppression ou gagne 1 pion Esquive.\"}","use":"passive"},"platoon commander":{"text":"{\"title\":\"•Commandant de Section\",\"body\":\"**Agent Impérial uniquement.**\\nPendant la __Mise en Place__, choisissez 1 unité de soldats de Corps alliée. L'unité choisie gagne **Escorte : Agent Impérial**.\\nTant que cette unité est engagée, elle gagne {adrenaline} : {critique} et adrénaline de défense : bloc si elle ne les a pas.\\nCette unité gagne **Tireur d'Élite 1**.\"}","use":"passive"},"point blank":{"text":"Quand cette unité effectue une attaque à distance contre une unité ennemie à ②, après avoir résolu l'attaque, cette unité gagne 1 pion Esquive.","use":"passive"},"prepared materiel":{"text":"Cache : Esquive 1.","use":"passive"},"programmed loyalty":{"text":"Dark Troopers Impériaux uniquement. Cette unité ne peut recevoir d'ordres que d'une unité du type indiqué sur la carte, et gagne Escorte : ce même type d'unité.","use":"passive"},"protector":{"text":"Quand cette unité utilise Gardien X, vous pouvez incliner cette carte pour annuler les résultats obtenus grâce à Gardien X comme s'il s'agissait de résultats Bloc. Redressez cette carte pendant la Phase Finale.","use":"exhaust"},"proton charge saboteur":{"text":"Commandos Rebelles uniquement. Ajoutez 1 figurine de Saboteur avec Charge à Protons. Quand cette arme est ajoutée à une réserve d'attaque, les autres armes à distance de cette réserve gagnent Assaut 1. (Carte mise à jour, erratum 17/06/2026 : Déflagration, Impact 6.)","use":"passive"},"proven tactician":{"text":"Officier Rebelle uniquement. Augmentez le courage de cette unité de 1. Tant qu'elles sont à portée 1 de cette unité, les unités de soldats alliées gagnent Renforts. Cette unité gagne Vivacité d'Esprit et Exemplaire.","use":"passive"},"pyke foot soldier concealment":{"text":"Cette unité conserve Cache : Viser 1 même si la figurine ajoutée par cette carte est vaincue.","use":"passive"},"pyke soldier electro whip":{"text":"Fantassins du Syndicat Pyke uniquement. Ajoutez 1 figurine de Soldat avec Électro-fouet. Arme : Électro-fouet (corps-à-corps et portée 1) — 2 dés rouges ; Immobiliser 1, Suppressif.","use":"passive"},"pyke soldier p13m disruptor":{"text":"Fantassins du Syndicat Pyke uniquement. Ajoutez 1 figurine de Soldat avec Disrupteur P13-M. Arme : Disrupteur P13-M (portée 1-4) — 1 dé rouge, 2 dés noirs ; Impact 1.","use":"passive"},"pyke syndicate crew":{"text":"{\"title\":\"Équipage du Syndicat Pyke\",\"body\":\"**Tank Speeder WLO-5 uniquement.**\\nCette unité perd l'affiliation Pirates et gagne l'affiliation Syndicat Pyke.\\nAu début de la __Phase d'Activation__, cette unité gagne 1 pion Viser ou 1 pion Esquive s'il y a au moins 1 autre unité Syndicat Pyke alliée à portée 1 de cette unité.\"}","use":"passive"},"pyke syndicate foot soldier squad":{"text":"{\"title\":\"Escouade de Fantassins du Syndicat Pyke\",\"body\":\"**Fantassins du Syndicat Pyke uniquement.**\\nAjoutez 5 figurines de Fantassin du Syndicat Pyke.\\nCette unité gagne **Indomptable** et 1 emplacement d'amélioration Personnel.\\nCette unité est en cohésion si toutes ses figurines sont à portée 1 du chef d'unité, au lieu de portée ½.\\nCette unité conserve ces règles même si ces figurines sont vaincues.\"}","use":"passive"},"r4 astromech droid":{"text":"Soldat Impérial ▲ uniquement. Ajoutez 1 figurine d'Astromech R4. Non-combattant. Cette unité gagne Réparation 1 : Capacité 2 (action).","use":"passive"},"r5 astromech droid":{"text":"Soldat Rebelle ▲ uniquement. Ajoutez 1 figurine de Droïde Astromech. Non-combattant. Réparation 1 : Capacité 2 (action).","use":"passive"},"range trooper":{"text":"Range Troopers uniquement. Ajoutez 1 figurine de Range Trooper.","use":"passive"},"rebel ambusher":{"text":"Ajoutez 1 figurine de Tireur Embusqué Rebelle. Cellule Dormante Rebelle uniquement. Action de carte (→) : si cette unité n'est pas engagée, choisissez une unité de soldats ennemie non engagée en LdV et lancez 1 dé d'attaque rouge : sur un résultat Touche ou Critique, l'unité choisie subit 1 blessure et gagne 1 pion Suppression.","use":"passive"},"rebel comms technician":{"text":"Soldat Rebelle ▲ uniquement. Ajoute 1 figurine de Technicien Comms Rebelle. Cette unité gagne 1 icône d'amélioration Comms et doit s'équiper d'au moins 1 amélioration Comms.","use":"passive"},"rebel officer":{"text":"Soldat ▲ uniquement. Ajoute 1 figurine d'Officier Rebelle. Chef. Cette unité augmente de 1 son courage et gagne Inspiration 1.","use":"passive"},"rebel trooper":{"text":"Soldats Rebelles uniquement. Ajoutez 1 figurine de Soldat Rebelle.","use":"passive"},"rebel trooper captain":{"text":"Soldats Rebelles uniquement. Ajoute 1 figurine de Capitaine Soldat Rebelle. Chef. Cette unité gagne 1 icône d'amélioration Entraînement. Au début de l'activation de cette unité, vous pouvez incliner cette carte (↱) : cette unité ne peut ni retirer de pions Suppression ni être démoralisée pendant cette activation.","use":"exhaust"},"rebel trooper specialist":{"text":"Soldats Rebelles uniquement. Ajoute 1 figurine de Spécialiste Soldat Rebelle. Cette unité gagne 1 icône d'amélioration Comms. Action de carte gratuite (↱») : cette unité gagne 1 pion Esquive ou 1 pion Adrénaline.","use":"exhaust"},"rebel trooper squad":{"text":"Soldats Rebelles uniquement. Ajoutez 5 figurines de Soldat Rebelle. Cette unité gagne Indomptable ; elle conserve ce mot-clé même si ces figurines ajoutées sont vaincues. Cette unité est en cohésion si toutes ses figurines sont à ① du Chef d'unité au lieu de ½ ; elle conserve cette règle même si ces figurines ajoutées sont vaincues. Cette unité ne peut pas être déployée ou recevoir des ordres via le mot-clé Transport.","use":"passive"},"rebel veteran":{"text":"Vétérans Rebelles uniquement. Ajoutez 1 figurine de Vétéran Rebelle.","use":"passive"},"rebel veteran squad":{"text":"Vétérans Rebelles uniquement. Ajoutez 5 figurines de Vétéran Rebelle. Cette unité gagne Indomptable ; elle conserve ce mot-clé même si ces figurines ajoutées sont vaincues. Cette unité est en cohésion si toutes ses figurines sont à ① du Chef d'unité au lieu de ½ ; elle conserve cette règle même si ces figurines ajoutées sont vaincues. Cette unité ne peut pas être déployée ou recevoir des ordres via le mot-clé Transport.","use":"passive"},"recon intel":{"text":"Cette unité gagne Éclaireur 1.","use":"passive"},"reluctant hero":{"text":"Agent Rebelle uniquement. Quand cette unité effectue une action Attaquer, pendant l'étape Former la Réserve d'Attaque, 1 de ses réserves d'attaque gagne Critique 1 pour chaque pion Suppression qu'elle a. Cette unité gagne Infiltration et Implacable.","use":"passive"},"remote doc":{"text":"Camion Speeder A-A5 uniquement. Action de carte (→) : choisissez une unité alliée de soldats non-droïdes à ① et en LdV de cette unité. Retirez 1 pion Blessure ou Poison, ou restaurez 1 figurine, de l'unité choisie. Ensuite, lancez 2 dés de défense blancs : l'unité choisie gagne 1 pion Suppression pour chaque résultat Bloc ou Adrénaline obtenu.","use":"passive"},"repeating blaster":{"text":"Officier Rebelle uniquement. Réduisez de 1 la vitesse maximale de cette unité. Cette unité gagne Précis 2.","use":"passive"},"rook kast":{"text":"Super Commandos Mandaloriens uniquement. Ajoutez 1 figurine de Rook Kast. Chef. Cette unité gagne Escorte : Maul. Arme : Pistolets Blaster de Rook (corps-à-corps et portée 1-2) — 2 dés rouges, 2 dés blancs.","use":"passive"},"rps 6 rocket gunner":{"text":"Landspeeder X-34 uniquement. Arme : Lance-roquettes RPS-6 (portée 2-4) — 1 dé rouge, 1 dé blanc, 1 dé noir ; Impact 2.","use":"passive"},"rt 97c dewback rider":{"text":"Soldat Monté sur Dewback uniquement. Arme : Fusil Blaster RT-97C (portée 1-4) — 1 dé rouge, 3 dés blancs.","use":"passive"},"rt 97c pintle mount":{"text":"Tank « Occupier » TX-225 GAVw uniquement. Arme : Fusil Blaster RT-97C (portée 1-4) — 1 dé rouge, 3 dés blancs.","use":"passive"},"rt 97c stormtrooper":{"text":"Stormtroopers uniquement. Ajoutez 1 figurine de Stormtrooper avec RT-97C. Arme : Fusil Blaster RT-97C (portée 1-4) — 1 dé rouge, 3 dés blancs.","use":"passive"},"ryder azadi":{"text":"Véhicule à répulseurs uniquement. Quand cette unité effectue un déplacement, vous pouvez incliner cette carte afin d'augmenter ou de réduire de 1 sa vitesse maximale.","use":"exhaust"},"saber throw":{"text":"Quand cette unité effectue une attaque avec cette arme, pendant l'étape « Constituer la réserve d'attaque », choisissez 1 des armes de corps-à-corps de cette unité. Les dés d'arme de cette arme sont égaux à la moitié du total de dés de l'arme choisie, arrondie au supérieur, et la réserve d'attaque gagne les mots-clés d'arme de l'arme choisie.","use":"passive"},"sabine s grapple line":{"text":"Sabine Wren uniquement. Action de carte (↱→, la carte s'incline) : choisissez une unité de soldats ennemie à ① et en LdV de cette unité. L'unité choisie gagne 2 pions Immobilisation et 2 pions Suppression.","use":"exhaust"},"scatter gun trooper":{"text":"Soldats de la Flotte uniquement. Ajoutez 1 figurine de Soldat avec Fusil à Dispersion. Arme : Fusil à Dispersion (corps-à-corps et portée 1-2) — 2 dés rouges ; Perforant 1.","use":"passive"},"secret ingredients":{"text":"{\"title\":\"•Ingrédients Secrets\",\"body\":\"**Logray uniquement.**\\nAu début de chaque round, placez 1 pion Viser ou 1 pion Esquive sur cette carte. Au début de l'activation de cette unité, elle peut retirer autant de pions de cette carte qu'elle le souhaite pour gagner autant de pions correspondants.\\nDe plus, après que cette unité a utilisé **Aide**, elle peut retirer 1 pion Suppression.\"}","use":"passive"},"security detail":{"text":"{\"title\":\"Détachement de Sécurité\",\"body\":\"**Death Troopers Impériaux uniquement.**\\nCette unité gagne **Gardien 2 : Haut Commandement Impérial** et **Escorte : commandant** {faction-empire}.\"}","use":"passive"},"seize the opportunity":{"text":"Commandant ou Agent uniquement. Pendant l'étape « Donner des ordres » de la Phase de Commandement, vous pouvez supprimer cette carte de la partie (icône ✖). Dans ce cas, cette unité se donne un ordre à elle-même.","use":"discard"},"serenity":{"text":"Côté Lumineux uniquement. Après qu'une autre unité alliée à ② de cette unité s'est ralliée, mais avant son étape « Effectuer des actions », vous pouvez incliner cette carte. Dans ce cas, lancez un nombre de dés de défense blancs égal au courage de cette unité. Pour chaque résultat Bloc ou Adrénaline obtenu, cette unité et l'unité alliée retirent 1 pion Suppression. Lorsque vous devriez incliner cette carte, vous pouvez la supprimer de la partie (✖) à la place : lancez alors des dés de défense rouges au lieu des blancs.","use":"both"},"shoretrooper":{"text":"Shoretroopers uniquement. Ajoutez 1 figurine de Shoretrooper.","use":"passive"},"shoretrooper squad expansion":{"text":"Shoretroopers uniquement. Ajoutez 5 figurines de Shoretrooper. Cette unité gagne Indomptable ; elle conserve ce mot-clé même si ces figurines ajoutées sont vaincues. Cette unité est en cohésion si toutes ses figurines sont à ① du Chef d'unité au lieu de ½ ; elle conserve cette règle même si ces figurines ajoutées sont vaincues. Cette unité ne peut pas être déployée ou recevoir des ordres via le mot-clé Transport.","use":"passive"},"shriv suurgav":{"text":"Cette unité gagne Commandant des Opérations. Action de carte gratuite (») : choisissez une unité de soldats alliée à ② de cette unité ; elle gagne 1 pion Esquive et peut gagner 1 pion Suppression.","use":"passive"},"situational awareness":{"text":"Cette unité gagne Manœuvre Improbable.","use":"passive"},"sleeper cell astromech":{"text":"Cellule Dormante Rebelle uniquement. Ajoute 1 figurine d'Astromech. Non-combattant. Quand cette unité termine un déplacement à ① d'au moins 1 pion Objectif, elle gagne 1 pion Esquive.","use":"passive"},"sm 9 dark trooper":{"text":"Dark Troopers Impériaux uniquement. Ajoutez 1 figurine de Dark Trooper avec Lanceur à Fragmentation SM-9. Arme : Lanceur à Fragmentation SM-9 (portée 1-2) — 2 dés rouges, 1 dé noir ; Déflagration, Cycle, Impact 2.","use":"passive"},"smoke grenades":{"text":"Pendant l'activation de cette unité, vous pouvez supprimer cette carte de la partie (icône ✖). Dans ce cas, cette unité effectue une action gratuite Fumée 1.","use":"discard"},"snowtrooper":{"text":"Snowtroopers uniquement. Ajoutez 1 figurine de Snowtrooper.","use":"passive"},"snowtrooper squad expansion":{"text":"Snowtroopers uniquement. Ajoutez 5 figurines de Snowtrooper. Cette unité gagne Indomptable ; elle conserve ce mot-clé même si ces figurines ajoutées sont vaincues. Cette unité est en cohésion si toutes ses figurines sont à ① du Chef d'unité au lieu de ½ ; elle conserve cette règle même si ces figurines ajoutées sont vaincues. Cette unité ne peut pas être déployée ou recevoir des ordres via le mot-clé Transport.","use":"passive"},"sonic charge saboteur":{"text":"Scout Troopers uniquement. Ajoutez 1 figurine de Saboteur avec Charge Sonique. Quand cette arme est ajoutée à une réserve d'attaque, les autres armes à distance de cette réserve gagnent Assaut 1. (Carte mise à jour, erratum 17/06/2026 : Déflagration, Impact 4, Suppressif.)","use":"passive"},"sonic imploders":{"text":"Arme : Imploseur Sonique (portée 1) — 1 dé noir ; Suppressif.","use":"passive"},"spotter link":{"text":"Quand une autre unité alliée déclare une attaque à distance contre une unité ennemie à ① et en LdV de cette unité, si cette unité ennemie n'est pas engagée au corps-à-corps, l'unité attaquante gagne Tireur d'Élite 1.","use":"passive"},"stormtrooper":{"text":"Stormtroopers uniquement. Ajoutez 1 figurine de Stormtrooper.","use":"passive"},"stormtrooper captain":{"text":"Stormtroopers uniquement. Ajoute 1 figurine de Capitaine Stormtrooper. Chef. Cette unité gagne 1 icône d'amélioration Entraînement. Au début de l'activation de cette unité, vous pouvez incliner cette carte (↱) : cette unité ne peut ni retirer de pions Suppression ni être démoralisée pendant cette activation.","use":"exhaust"},"stormtrooper marksman":{"text":"{\"title\":\"Tireur d'Élite Stormtrooper\",\"body\":\"**Escouade Stormtrooper Antiémeute uniquement.**\\nAjoutez 1 figurine de Tireur d'Élite Stormtrooper.\\n{action}Si cette unité n'est pas engagée, choisissez une unité de soldats ennemie non engagée en LdV et lancez 1 dé d'attaque rouge. Sur un {touche} ou un {critique}, l'unité choisie subit 1 blessure et gagne 1 pion Suppression.\"}","use":"passive"},"stormtrooper sharpshooter":{"text":"Antiémeute uniquement. Ajoute 1 figurine de Tireur Embusqué Stormtrooper. Action de carte (→) : si cette unité n'est pas engagée, choisissez une unité de soldats ennemie non engagée en LdV et lancez 1 dé d'attaque rouge : sur un résultat Touche ou Critique, l'unité choisie subit 1 blessure et gagne 1 pion Suppression.","use":"passive"},"stormtrooper specialist":{"text":"Cette unité gagne 1 icône d'amélioration ; l'action associée (gagner 1 pion Viser ou 1 pion Adrénaline) est propre à la carte.","use":"exhaust"},"stormtrooper squad":{"text":"Stormtroopers uniquement. Ajoutez 5 figurines de Stormtrooper. Cette unité gagne Indomptable ; elle conserve ce mot-clé même si ces figurines ajoutées sont vaincues. Cette unité est en cohésion si toutes ses figurines sont à ① du Chef d'unité au lieu de ½ ; elle conserve cette règle même si ces figurines ajoutées sont vaincues. Cette unité ne peut pas être déployée ou recevoir des ordres via le mot-clé Transport.","use":"passive"},"stormtrooper squad expansion":{"text":"Stormtroopers uniquement. Ajoutez 5 figurines de Stormtrooper. Cette unité gagne Indomptable ; elle conserve ce mot-clé même si ces figurines ajoutées sont vaincues. Cette unité est en cohésion si toutes ses figurines sont à ① du Chef d'unité au lieu de ½ ; elle conserve cette règle même si ces figurines ajoutées sont vaincues. Cette unité ne peut pas être déployée ou recevoir des ordres via le mot-clé Transport.","use":"passive"},"strict orders":{"text":"Pendant la Phase d'Activation, quand une unité alliée qui a un pion Ordre face visible commence son étape « Se rallier », elle peut choisir de retirer 1 pion Suppression au lieu de lancer les dés.","use":"passive"},"stun baton":{"text":"{\"title\":\"Bâton Étourdissant\",\"body\":\"**Agent Impérial ou Officier Impérial uniquement.**\\nCette unité gagne **Démoraliser 1**.\",\"weapons\":[{\"name\":\"Bâton Étourdissant\",\"keywords\":\"Immobiliser 1\"}]}","use":"passive"},"super commando concealment":{"text":"Cette unité conserve Cache : Adrénaline 2 même si la figurine ajoutée par cette carte est vaincue.","use":"passive"},"super commando marksman":{"text":"Super Commandos Mandaloriens uniquement. Ajoutez 1 figurine de Super Commando Tireur Embusqué. Arme : Tireur Embusqué Désigné (portée 1-3) — 1 dé rouge, 1 dé noir ; Létal 1.","use":"passive"},"super commando pistoleer":{"text":"Super Commandos Mandaloriens uniquement. Ajoutez 1 figurine de Super Commando Pistolero. Arme : Paire de Pistolets Blaster (corps-à-corps et portée 1-2) — 2 dés rouges, 2 dés blancs ; Débordement.","use":"passive"},"sx 21 mudtrooper":{"text":"{\"title\":\"Mudtrooper avec SX-21\",\"body\":\"**Mudtroopers Impériaux uniquement.**\\nAjoutez 1 figurine de Mudtrooper avec SX-21.\",\"weapons\":[{\"name\":\"Fusil à Dispersion SX-21\",\"keywords\":\"Assaut 2\"}]}","use":"passive"},"sx 21 trooper":{"text":"Soldats Rebelles uniquement. Ajoutez 1 figurine de Soldat avec SX-21. Arme : Blaster à Dispersion SX-21 (portée 1-2) — 2 dés rouges, 2 dés blancs ; Impact 1.","use":"passive"},"t 21 dewback rider":{"text":"Soldat Monté sur Dewback uniquement. Arme : Fusil Blaster T-21 (portée 1-3) — 4 dés blancs ; Critique 2.","use":"passive"},"t 21 special forces trooper":{"text":"Forces Spéciales Impériales uniquement. Ajoutez 1 figurine de Soldat avec T-21. Arme : Blaster à Répétition T-21 (portée 1-3) — 4 dés blancs ; Critique 2.","use":"passive"},"t 21 stormtrooper":{"text":"Stormtroopers uniquement. Ajoutez 1 figurine de Stormtrooper avec T-21. Arme : Blaster à Répétition T-21 (portée 1-3) — 4 dés blancs ; Critique 2.","use":"passive"},"t 21a range trooper":{"text":"Range Troopers uniquement. Ajoutez 1 figurine de Range Trooper avec T-21A. Arme : Blaster à Répétition T-21A (portée 1-4) — 2 dés blancs, 2 dés noirs ; Suppressif.","use":"passive"},"t 21b shoretrooper":{"text":"Shoretroopers uniquement. Ajoutez 1 figurine de Shoretrooper avec T-21B. Arme : Blaster à Répétition T-21B (portée 1-4) — 2 dés blancs, 2 dés noirs ; Critique 1.","use":"passive"},"t 7 ion snowtrooper":{"text":"Snowtroopers uniquement. Ajoutez 1 figurine de Snowtrooper avec T-7 à Ions. Arme : Fusil T-7 à Ions (portée 1-3) — 1 dé blanc, 2 dés noirs ; Critique 1, Impact 1, Ion 1.","use":"passive"},"tank hunting munitions":{"text":"Quand cette unité attaque, pendant l'étape Former la Réserve d'Attaque, vous pouvez ✖ cette carte. Dans ce cas, cette Réserve d'Attaque gagne Anti-matériel 2 et Impact 2.","use":"discard"},"targeting scopes":{"text":"Cette unité gagne Précis 1.","use":"passive"},"tech":{"text":"Le Bad Batch uniquement. Ajoutez 1 figurine de Tech. Cette unité gagne Tacticien 1 et Cache : Viser 1 et Esquive 1.","use":"passive"},"tenacity":{"text":"Quand cette unité effectue une attaque au corps-à-corps, pendant l'étape « Constituer la réserve d'attaque », si elle a 1 ou plusieurs pions Blessure ou si 1 ou plusieurs de ses figurines sont vaincues, elle peut ajouter 1 dé d'attaque rouge à ses réserves d'attaque.","use":"passive"},"the darksaber":{"text":"Sabine Wren uniquement. Cette unité gagne Intrépide et Immunité : Perforant au Corps-à-Corps. Arme : Le Sabre Noir (corps-à-corps) — 5 dés noirs ; Impact 1, Perforant 1.","use":"passive"},"tip of the spear":{"text":"{\"title\":\"•Fer de Lance\",\"body\":\"**Agent Impérial ou Officier Impérial uniquement.**\\nQuand cette unité reçoit un ordre, une unité alliée à portée 1 peut retirer jusqu'à 1 pion Suppression.\\nCette unité gagne **Aide : unité de soldats** {faction-empire}, **Ordre Direct : unité de soldats de Corps** et **Tacticien 1**.\"}","use":"passive"},"tl tt flame projector":{"text":"TL-TT uniquement. Arme : Lance-flammes (corps-à-corps et portée 1) — 2 dés noirs ; Fixe : avant, Déflagration, Souffle.","use":"passive"},"tl tt laser cannon":{"text":"TL-TT uniquement. Arme : Canon Laser (portée 2-4) — 1 dé rouge, 2 dés noirs ; Fixe : avant, Impact 3.","use":"passive"},"tl tt rotary blaster":{"text":"TL-TT uniquement. Arme : Blaster Rotatif (portée 1-3) — 5 dés noirs ; Fixe : avant.","use":"passive"},"tristan wren":{"text":"Résistance Mandalorienne uniquement. Ajoutez 1 figurine de Tristan Wren. Arme : Blaster de Tristan (portée 1-3) — 2 dés noirs ; Létal 1, Suppressif.","use":"passive"},"trusted agent":{"text":"Unique. Pendant l'étape « Donner des ordres » de la Phase de Commandement, vous pouvez supprimer cette carte de la partie (✖). Dans ce cas, choisissez une unité ▲ alliée : cette unité peut donner un ordre à l'unité choisie, quelle que soit son affiliation.","use":"discard"},"underworld contacts":{"text":"Cette unité gagne Alliés de Circonstance.","use":"passive"},"unorthodox tactician":{"text":"Camion Speeder A-A5 uniquement. Au début de l'activation de cette unité, lancez 3 dés de défense rouges. Pour chaque résultat Bloc ou Adrénaline obtenu, choisissez une unité alliée différente à ③. Chaque unité choisie gagne 1 pion Viser.","use":"passive"},"unstable astromech":{"text":"Landspeeder X-34 uniquement. À la fin de l'activation de cette unité, vous pouvez supprimer cette carte de la partie (icône ✖). Dans ce cas, cette unité peut effectuer une attaque ou se déplacer. Ensuite, après que l'effet a été résolu, lancez 3 dés d'attaque noirs. Cette unité subit 1 blessure pour chaque résultat Touche ou Critique obtenu.","use":"discard"},"ursa wren":{"text":"Résistance Mandalorienne uniquement. Ajoutez 1 figurine d'Ursa Wren. Chef. Cette unité gagne Intrépide. Arme : Blaster d'Ursa (corps-à-corps et portée 1-2) — 1 dé rouge, 1 dé blanc, 1 dé noir ; Longue Distance.","use":"passive"},"vibro axe":{"text":"Agent Rebelle ou Officier Rebelle uniquement. Cette unité gagne Charge. Vibrohache (1 rouge, 3 noirs, corps-à-corps) : Impact 1, Létal 1.","use":"passive"},"vigilance":{"text":"Au début de l'étape « Retirer les pions », choisissez soit 1 unité de soldats alliée à ② de cette unité, soit jusqu'à 2 unités de soldats ▲ alliées à ② de cette unité. Chaque unité choisie ne retire pas jusqu'à 1 pion Esquive.","use":"passive"},"wedge antilles":{"text":"Véhicule à répulseurs Rebelle uniquement. Cette unité gagne Commandant des Opérations. Action de carte gratuite (↱») : cette unité effectue un pivot.","use":"exhaust"},"weequay captain":{"text":"{\"title\":\"Capitaine Weequay\",\"body\":\"**Pirates Weequays uniquement.**\\nAjoutez 1 figurine de Capitaine Weequay. **Chef.**\\nAu début de l'activation de cette unité, vous pouvez incliner cette carte. Dans ce cas, cette unité ne peut ni retirer de pions Suppression ni être réprimée pendant son activation.\",\"weapons\":[{\"name\":\"Bravade\",\"keywords\":\"\"}]}","use":"exhaust"},"weequay crew":{"text":"{\"title\":\"Équipage Weequay\",\"body\":\"**Tank Speeder WLO-5 uniquement.**\\nAu début de la __Phase d'Activation__, cette unité gagne 1 pion Viser ou 1 pion Esquive s'il y a au moins 1 autre unité Pirates alliée à portée 1 de cette unité.\"}","use":"passive"},"weequay pirate squad":{"text":"{\"title\":\"Escouade de Pirates Weequays\",\"body\":\"**Pirates Weequays uniquement.**\\nAjoutez 4 figurines de Pirate Weequay.\\nCette unité gagne **Indomptable**. Elle conserve ce mot-clé même si ces figurines sont vaincues.\\nCette unité est en cohésion si toutes ses figurines sont à portée 1 du chef d'unité, au lieu de portée ½. Elle conserve cette règle même si ces figurines sont vaincues.\\nCette unité ne peut pas être déployée ni recevoir d'ordre grâce au mot-clé **Transport**, sauf si l'unité dotée de **Transport** a la même affiliation.\"}","use":"passive"},"weequay pirates":{"text":"{\"name\":\"Pirates Weequays\",\"type\":\"Soldat\",\"keywords\":[\"Mercenaire : {faction-empire}{faction-rebelles}{faction-republique}{faction-separatistes}\",\"Charge\",\"Autonome : Viser 1\",\"Instinct de Survie\",\"Matamore\"],\"weapons\":[{\"name\":\"Vibrolame\",\"keywords\":\"\"},{\"name\":\"Blaster Weequay\",\"keywords\":\"Polyvalent\"}]}","use":null},"wet weather gear stormtrooper":{"text":"{\"name\":\"Stormtroopers en Équipement Pluie\",\"type\":\"Soldat\",\"keywords\":[\"Coordination : Mudtroopers Impériaux\",\"Profil Bas\",\"Position Préparée\",\"Sans Entrave\"],\"weapons\":[{\"name\":\"Matraque\",\"keywords\":\"\"},{\"name\":\"Fusil Blaster E-11\",\"keywords\":\"Assaut 1\"}]}","use":null},"wicket hero of bright tree":{"text":"{\"name\":\"Wicket\",\"subtitle\":\"Héros de l'Arbre Lumineux\",\"type\":\"Soldat\",\"keywords\":[\"Mercenaire : {faction-rebelles}\",\"Autonome : Esquive 1\",\"Profil Bas. Agile\",\"Implacable\",\"Éclaireur 1. Équipe d'Éclaireurs 2\",\"Sans Entrave\"],\"weapons\":[{\"name\":\"Lance\",\"keywords\":\"Perforant 1\"},{\"name\":\"Fronde\",\"keywords\":\"Perforant 1, Primitif\"}]}","use":null},"wlo 5 speeder tank":{"text":"{\"name\":\"Tank Speeder WLO-5\",\"type\":\"Véhicule à Répulseurs\",\"keywords\":[\"Mercenaire : {faction-empire}{faction-rebelles}{faction-republique}{faction-separatistes}\",\"Armure 5\",\"Arsenal 2\",\"Sustentation : Terrestre\",\"Transport\",\"Point Faible 2 : Arrière\"],\"weapons\":[{\"name\":\"Lasers Antipersonnel\",\"keywords\":\"Fixe : Avant\"},{\"name\":\"Canon Laser Lourd\",\"keywords\":\"Impact 2\"}]}","use":null},"wrecker":{"text":"Ajoute 1 figurine de Wrecker. Tant que cette figurine est sur le champ de bataille, l'Alter Ego Omega de cette unité ne peut pas se voir assigner de blessures.","use":"passive"},"x 34 mark ii blaster":{"text":"Landspeeder X-34 uniquement. Arme : Blaster Moyen Mark II (portée 1-3) — 4 dés noirs ; Fixe : avant.","use":"passive"},"xs iv dark trooper":{"text":"Dark Troopers Impériaux uniquement. Ajoutez 1 figurine de Dark Trooper avec Canon d'Assaut XS-IV. Arme : Canon d'Assaut XS-IV (portée 1-3) — 4 dés noirs ; Critique 1.","use":"passive"},"z 6 mudtrooper":{"text":"{\"title\":\"Mudtrooper avec Z-6\",\"body\":\"**Mudtroopers Impériaux uniquement.**\\nAjoutez 1 figurine de Mudtrooper avec Z-6.\",\"weapons\":[{\"name\":\"Blaster Rotatif Z-6\",\"keywords\":\"Anti-personnel 3\"}]}","use":"passive"},"z 6 riot baton":{"text":"{\"title\":\"Matraque Anti-émeute Z-6\",\"body\":\"**Agent Impérial ou Officier Impérial uniquement.**\\nCette unité gagne **Immunité : Perforant au Corps-à-Corps**.\",\"weapons\":[{\"name\":\"Matraque Anti-émeute Z-6\",\"keywords\":\"Suppressif\"}]}","use":"passive"},"z 6 trooper":{"text":"Soldats Rebelles uniquement. Ajoutez 1 figurine de Soldat avec Z-6. Arme : Blaster Rotatif Z-6 (portée 1-3) — 6 dés blancs.","use":"passive"}};
